import React from 'react';
import { DigoAsset } from '@digo-org/digo-api';
import {
  ComposedChart,
  Area,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from 'recharts';

export class Asset extends DigoAsset {
  constructor() {
    super();
  }

  render() {
    // Global parameters
    const backgroundColor = (this.globalParameters?.['background-color'] as string) || '#0a1628';
    const lineColor = (this.globalParameters?.['line-color'] as string) || '#60a5fa';
    const bandColor = (this.globalParameters?.['band-color'] as string) || '#3b82f6';
    const bandOpacity = (this.globalParameters?.['band-opacity'] as number) ?? 0.25;
    const showGrid = (this.globalParameters?.['show-grid'] as boolean) ?? true;
    const showLegend = (this.globalParameters?.['show-legend'] as boolean) ?? true;
    const chartTitle = (this.globalParameters?.['chart-title'] as string) || 'Sea Level Rise Projections (2025\u20132075)';
    const showTitle = (this.globalParameters?.['show-title'] as boolean) ?? true;
    const lineWidth = (this.globalParameters?.['line-width'] as number) ?? 2.5;
    const gridColor = (this.globalParameters?.['grid-color'] as string) || '#1e3a5f';
    const textColor = (this.globalParameters?.['text-color'] as string) || '#94a3b8';

    // Instance parameters (time series arrays from the first row)
    const centralData = (this.instances?.[0]?.['central-projection'] as number[]) || [];
    const upperData = (this.instances?.[0]?.['upper-bound'] as number[]) || [];
    const lowerData = (this.instances?.[0]?.['lower-bound'] as number[]) || [];

    // Build chart data by mapping timeArray to values
    const chartData = this.timeArray?.map((time: string, index: number) => {
      const central = centralData[index] ?? 0;
      const upper = upperData[index] ?? 0;
      const lower = lowerData[index] ?? 0;
      return {
        year: time,
        central,
        upper,
        lower,
        bandBase: lower,
        bandRange: Math.max(0, upper - lower),
      };
    }) || [];

    // Custom tooltip
    const CustomTooltip = ({ active, payload, label }: any) => {
      if (active && payload && payload.length > 0) {
        const dataPoint = payload[0]?.payload;
        if (!dataPoint) return null;
        return (
          <div style={{
            backgroundColor: 'rgba(10, 22, 40, 0.95)',
            border: '1px solid #1e3a5f',
            borderRadius: '8px',
            padding: '12px 16px',
            color: '#e2e8f0',
            fontSize: '13px',
            lineHeight: '1.6',
            boxShadow: '0 4px 12px rgba(0,0,0,0.4)',
          }}>
            <div style={{ fontWeight: 600, marginBottom: '6px', color: '#f1f5f9', fontSize: '14px' }}>
              Year: {label}
            </div>
            <div style={{ color: lineColor }}>
              Central Projection: <strong>{dataPoint.central?.toFixed(1)} mm</strong>
            </div>
            <div style={{ color: '#93c5fd' }}>
              Upper Bound: <strong>{dataPoint.upper?.toFixed(1)} mm</strong>
            </div>
            <div style={{ color: '#7dd3fc' }}>
              Lower Bound: <strong>{dataPoint.lower?.toFixed(1)} mm</strong>
            </div>
          </div>
        );
      }
      return null;
    };

    // Custom legend
    const renderLegend = () => {
      return (
        <div style={{ display: 'flex', justifyContent: 'center', gap: '24px', paddingTop: '8px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <div style={{ width: '20px', height: '3px', backgroundColor: lineColor, borderRadius: '2px' }} />
            <span style={{ color: textColor, fontSize: '12px' }}>Central Projection</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <div style={{ width: '20px', height: '12px', backgroundColor: bandColor, opacity: bandOpacity, borderRadius: '2px' }} />
            <span style={{ color: textColor, fontSize: '12px' }}>Confidence Interval</span>
          </div>
        </div>
      );
    };

    return (
      <div style={{
        width: '100%',
        height: '100%',
        backgroundColor,
        display: 'flex',
        flexDirection: 'column',
        padding: '20px',
        boxSizing: 'border-box',
        fontFamily: "'Inter', 'Segoe UI', system-ui, sans-serif",
      }}>
        {showTitle && (
          <h2 style={{
            color: '#e2e8f0',
            textAlign: 'center',
            margin: '0 0 16px 0',
            fontSize: '18px',
            fontWeight: 600,
            letterSpacing: '-0.01em',
          }}>
            {chartTitle}
          </h2>
        )}
        <div style={{ flex: 1, width: '100%', minHeight: 0 }}>
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={chartData} margin={{ top: 10, right: 30, left: 20, bottom: 20 }}>
              {showGrid && (
                <CartesianGrid strokeDasharray="3 3" stroke={gridColor} strokeOpacity={0.5} />
              )}
              <XAxis
                dataKey="year"
                stroke={textColor}
                tick={{ fill: textColor, fontSize: 12 }}
                label={{ value: 'Year', position: 'insideBottom', offset: -10, fill: textColor, fontSize: 13, fontWeight: 500 }}
                tickLine={{ stroke: textColor }}
              />
              <YAxis
                stroke={textColor}
                tick={{ fill: textColor, fontSize: 12 }}
                label={{ value: 'Sea Level Rise (mm)', angle: -90, position: 'insideLeft', offset: -5, fill: textColor, fontSize: 13, fontWeight: 500, style: { textAnchor: 'middle' } }}
                tickLine={{ stroke: textColor }}
              />
              <Tooltip content={<CustomTooltip />} />
              {/* Confidence band: invisible base area (lower bound) */}
              <Area type="monotone" dataKey="bandBase" stackId="confidence" fill="transparent" stroke="none" activeDot={false} isAnimationActive={true} />
              {/* Confidence band: visible range area (upper - lower) */}
              <Area type="monotone" dataKey="bandRange" stackId="confidence" fill={bandColor} fillOpacity={bandOpacity} stroke="none" activeDot={false} isAnimationActive={true} animationDuration={1500} />
              {/* Central projection line */}
              <Line type="monotone" dataKey="central" stroke={lineColor} strokeWidth={lineWidth} dot={false} activeDot={{ r: 5, fill: lineColor, stroke: '#ffffff', strokeWidth: 2 }} isAnimationActive={true} animationDuration={2000} />
              {showLegend && <Legend content={renderLegend} />}
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      </div>
    );
  }
}
